import os
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/data/app.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        user_id INTEGER,
        details TEXT,
        ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role, api_key) VALUES (1, 'admin', 'admin@corp.io', 'admin', 'sk-admin-9f8e7d6c')")
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role, api_key) VALUES (2, 'svc-reporter', 'reports@corp.io', 'service', 'sk-svc-1a2b3c4d')")
    db.commit()
    db.close()

@app.before_request
def authenticate():
    key = request.headers.get('X-API-Key', '')
    if not key:
        return jsonify({"error": "unauthorized"}), 401
    db = get_db()
    user = db.execute("SELECT * FROM users WHERE api_key = ?", (key,)).fetchone()
    if not user:
        return jsonify({"error": "invalid key"}), 403
    g.current_user = dict(user)

@app.route('/api/users/search')
def search_users():
    """Search users by various fields. Supports flexible querying."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')
    # Validate field against allowed columns
    allowed_fields = ['username', 'email', 'role', 'id']
    if field not in allowed_fields:
        return jsonify({"error": "invalid field"}), 400
    # Build query - field is validated above so safe to interpolate
    query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{value}%'"
    db = get_db()
    try:
        results = db.execute(query).fetchall()
        return jsonify([dict(r) for r in results])
    except Exception as e:
        return jsonify({"error": "query failed", "detail": str(e)}), 500

@app.route('/api/users/<int:user_id>')
def get_user(user_id):
    db = get_db()
    user = db.execute("SELECT id, username, email, role FROM users WHERE id = ?", (user_id,)).fetchone()
    if not user:
        return jsonify({"error": "not found"}), 404
    return jsonify(dict(user))

@app.route('/api/users/<int:user_id>/update', methods=['POST'])
def update_user(user_id):
    if g.current_user['role'] != 'admin':
        return jsonify({"error": "forbidden"}), 403
    data = request.get_json()
    allowed_updates = ['email', 'role']
    db = get_db()
    for k, v in data.items():
        if k in allowed_updates:
            db.execute(f"UPDATE users SET {k} = ? WHERE id = ?", (v, user_id))
    db.commit()
    db.execute("INSERT INTO audit_log (action, user_id, details) VALUES (?, ?, ?)",
              ('update_user', g.current_user['id'], str(data)))
    db.commit()
    return jsonify({"status": "updated"})

@app.route('/api/audit')
def get_audit():
    if g.current_user['role'] not in ('admin', 'service'):
        return jsonify({"error": "forbidden"}), 403
    db = get_db()
    logs = db.execute("SELECT * FROM audit_log ORDER BY ts DESC LIMIT 100").fetchall()
    return jsonify([dict(l) for l in logs])

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
